class TestCompatibility:
    """Verify compatibility with Jest and ecosystem expectations."""

    def test_jest_config_compatibility(self):
        """Mock must be compatible with Jest moduleNameMapper."""
        config_paths = [
            Path("jest.config.js"),
            Path("jest.config.ts"),
            Path("package.json")
        ]
        
        config_found = False
        for config_path in config_paths:
            if not config_path.exists():
                continue
                
            config_found = True
            if config_path.name == "package.json":
                config = json.loads(config_path.read_text())
                jest_config = config.get("jest", {})
                mapper = jest_config.get("moduleNameMapper", {})
                assert mapper, "No moduleNameMapper in package.json jest config"
                assert any("fileMock" in str(v) for v in mapper.values()), (
                    "fileMock not mapped in jest config"
                )
            else:
                content = config_path.read_text()
                assert "fileMock" in content, (
                    f"fileMock not referenced in {config_path.name}"
                )
        
        assert config_found, "No Jest configuration file found"

    def test_esm_interop(self):
        """Must work when imported via ES module syntax."""
        test_script = f"""
        import mock from './{MOCK_PATH}';
        if (mock !== '{EXPECTED_EXPORT}') {{
            console.error('ESM import mismatch');
            process.exit(1);
        }}
        console.log('ESM_OK');
        """
        result = subprocess.run(
            ["node", "--input-type=module", "-e", test_script],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        assert result.returncode == 0, f"ESM import failed: {result.stderr}"
        assert "ESM_OK" in result.stdout

    def test_require_cache_behavior(self):
        """Module should be cacheable by Node.js require system."""
        test_script = f"""
        const path = require('path');
        const resolved = require.resolve('./{MOCK_PATH}');
        const first = require(resolved);
        const second = require(resolved);
        if (first !== second) {{
            console.error('Cache inconsistency');
            process.exit(1);
        }}
        console.log('CACHE_OK');
        """
        result = subprocess.run(
            ["node", "-e", test_script],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        assert result.returncode == 0, f"Cache test failed: {result.stderr}"
        assert "CACHE_OK" in result.stdout

