class TestPerformance:
    """Verify loading performance characteristics."""

    def test_load_time_bounded(self):
        """Module load time must be under 100ms."""
        test_script = f"""
        const start = process.hrtime.bigint();
        require('./{MOCK_PATH}');
        const end = process.hrtime.bigint();
        const ms = Number(end - start) / 1e6;
        if (ms > 100) {{
            console.error(`Load time too high: ${{ms}}ms`);
            process.exit(1);
        }}
        console.log(`LOAD_TIME_MS:${{ms.toFixed(2)}}`);
        """
        result = subprocess.run(
            ["node", "-e", test_script],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        assert result.returncode == 0, f"Performance failure: {result.stderr}"
        assert "LOAD_TIME_MS:" in result.stdout

    def test_memory_footprint(self):
        """Module should have minimal memory footprint."""
        test_script = f"""
        const before = process.memoryUsage().heapUsed;
        require('./{MOCK_PATH}');
        const after = process.memoryUsage().heapUsed;
        const delta = after - before;
        if (delta > 1024 * 1024) {{  // 1MB threshold
            console.error(`Memory usage too high: ${{delta}} bytes`);
            process.exit(1);
        }}
        console.log(`MEMORY_DELTA:${{delta}}`);
        """
        result = subprocess.run(
            ["node", "-e", test_script],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        assert result.returncode == 0, f"Memory failure: {result.stderr}"
        assert "MEMORY_DELTA:" in result.stdout

